package com.personal.crm;
import android.Manifest;
import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.os.Build;
import org.json.*;
import java.time.*;
import java.util.*;
final class Reminders {
 static final String CHANNEL="reach_out",ACTION="com.personal.crm.REMIND";
 static long advance(long time,int count,String unit,ZoneId zone){ZonedDateTime date=Instant.ofEpochMilli(time).atZone(zone);return (unit.equals("months")?date.plusMonths(count):unit.equals("weeks")?date.plusWeeks(count):date.plusDays(count)).toInstant().toEpochMilli();}
 static boolean allowed(Context c){return (Build.VERSION.SDK_INT<33||c.checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)==PackageManager.PERMISSION_GRANTED)&&c.getSystemService(NotificationManager.class).areNotificationsEnabled();}
 static void channel(Context c){NotificationChannel channel=new NotificationChannel(CHANNEL,"Reach-out reminders",NotificationManager.IMPORTANCE_DEFAULT);channel.setDescription("Reminders to contact people on your schedule");c.getSystemService(NotificationManager.class).createNotificationChannel(channel);}
 private static PendingIntent alarm(Context c){return PendingIntent.getBroadcast(c,0,new Intent(c,ReminderReceiver.class).setAction(ACTION),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
 static void schedule(Context c){synchronized(CrmStore.LOCK){AlarmManager manager=c.getSystemService(AlarmManager.class);manager.cancel(alarm(c));if(!allowed(c))return;try{JSONArray people=new CrmStore(c).read().getJSONArray("people");long earliest=Long.MAX_VALUE;for(int i=0;i<people.length();i++){JSONObject p=people.getJSONObject(i);if(p.optBoolean("reminders")&&p.optLong("nextAt")>0)earliest=Math.min(earliest,p.getLong("nextAt"));}if(earliest!=Long.MAX_VALUE)manager.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,Math.max(System.currentTimeMillis()+1000,earliest),alarm(c));}catch(JSONException e){throw new IllegalStateException(e);}}}
 static void deliver(Context c){synchronized(CrmStore.LOCK){channel(c);if(!allowed(c))return;CrmStore store=new CrmStore(c);JSONObject state=store.read();long now=System.currentTimeMillis();try{JSONArray rows=state.getJSONArray("people");List<JSONObject> due=new ArrayList<>();for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);if(!p.optBoolean("reminders")||p.optLong("nextAt")<=0||p.getLong("nextAt")>now)continue;due.add(new JSONObject(p.toString()));long next=p.getLong("nextAt");do{next=advance(next,p.getInt("every"),p.getString("unit"),ZoneId.systemDefault());}while(next<=now);p.put("nextAt",next);}if(!due.isEmpty())store.write(state);for(JSONObject p:due){String id=p.getString("id");Intent open=new Intent(c,MainActivity.class).setData(android.net.Uri.parse("crm://person/"+android.net.Uri.encode(id))).putExtra("personId",id).addFlags(Intent.FLAG_ACTIVITY_SINGLE_TOP);PendingIntent content=PendingIntent.getActivity(c,0,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Intent done=new Intent(c,ReminderReceiver.class).setAction("CONTACTED").setData(android.net.Uri.parse("crm://contacted/"+android.net.Uri.encode(id))).putExtra("personId",id);PendingIntent action=PendingIntent.getBroadcast(c,0,done,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification note=new Notification.Builder(c,CHANNEL).setSmallIcon(com.personal.crm.R.drawable.ic_notification).setContentTitle("Time to reach out").setContentText(p.getString("name")).setContentIntent(content).setAutoCancel(true).setVisibility(Notification.VISIBILITY_PRIVATE).addAction(new Notification.Action.Builder(null,"Contacted today",action).build()).build();c.getSystemService(NotificationManager.class).notify(id,1,note);}}catch(JSONException e){throw new IllegalStateException(e);}schedule(c);}}
 static boolean contacted(Context c,String id){synchronized(CrmStore.LOCK){try{CrmStore store=new CrmStore(c);JSONObject state=store.read();JSONArray rows=state.getJSONArray("people");for(int i=0;i<rows.length();i++){JSONObject p=rows.getJSONObject(i);if(!p.getString("id").equals(id))continue;long now=System.currentTimeMillis();p.put("lastAt",now);long baseline=p.optLong("nextAt",now);ZonedDateTime old=Instant.ofEpochMilli(baseline>0?baseline:now).atZone(ZoneId.systemDefault());ZonedDateTime today=Instant.ofEpochMilli(now).atZone(ZoneId.systemDefault()).withHour(old.getHour()).withMinute(old.getMinute()).withSecond(0).withNano(0);p.put("nextAt",advance(today.toInstant().toEpochMilli(),p.getInt("every"),p.getString("unit"),ZoneId.systemDefault()));store.write(state);c.getSystemService(NotificationManager.class).cancel(id,1);schedule(c);return true;}return false;}catch(JSONException e){return false;}}}
}
